// Build the House 001 browser viewer as a single /worlds/ asset.
// Source remains canonical in public/living-worlds/ and public/worlds/.
// No third-party bundler, package installation, network or hosted service required.
import {readFile,writeFile} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
export const HOUSE_VIEW_SOURCES=[
  'public/living-worlds/house-core.mjs',
  'public/living-worlds/house-world-bridge.mjs',
  'public/worlds/house-visual.mjs',
  'public/worlds/house-mode.mjs'
];
const DEST='public/worlds/house-mode.bundle.mjs';
export async function buildHouseViewBundle(){
  const parts=[];
  for(const filename of HOUSE_VIEW_SOURCES){
    const source=await readFile(path.join(root,filename),'utf8');
    const imports=source.match(/^import .*;$/gm)||[];
    if(imports.some(line=>!/^import \{[a-zA-Z0-9_, ]+\} from '\.\.\/[^']+\.mjs';$/.test(line)&&
      !/^import \{[a-zA-Z0-9_, ]+\} from '\.\/[^']+\.mjs';$/.test(line))){
      throw Error('house_bundle_unapproved_import:'+filename);
    }
    const stripped=source.replace(/^import .*;\n/gm,'');
    if(/^import /m.test(stripped))throw Error('house_bundle_unbundled_import:'+filename);
    parts.push({filename,source,stripped});
  }
  return [
    '// GENERATED FROM CANONICAL EVERCRAFT HOUSE SOURCES. DO NOT EDIT THIS FILE.',
    '// Generator: scripts/build-house-worlds-bundle.mjs',
    '// Browser-only projection; it does not run the authoritative TypeScript World Engine.',
    ...parts.map(p=>'\n// ===== '+p.filename+' =====\n'+p.stripped.trimEnd()+'\n')
  ].join('\n')+'\n';
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  const output=await buildHouseViewBundle();
  const target=path.join(root,DEST);
  if(process.argv.includes('--check')){
    const actual=await readFile(target,'utf8').catch(()=>null);
    if(actual!==output)throw Error('house_bundle_out_of_date: run node scripts/build-house-worlds-bundle.mjs');
    process.stdout.write('House 001 viewer bundle matches canonical sources.\n');
  }else{
    await writeFile(target,output,'utf8');
    process.stdout.write('Wrote '+DEST+' from '+HOUSE_VIEW_SOURCES.length+' owned source modules.\n');
  }
}
